with ThreadPoolExecutor(max_workers=8) as pool:
    http_results = list(pool.map(check_public, entries))
for path in ('libros/', 'libros/otros/'):
    with urlopen(PUBLIC + path, timeout=60) as response:
        assert b'fisica-preuniversitaria/index.html' in response.read(), path
(OUTPUT / 'public-http-report.json').write_text(json.dumps(http_results, ensure_ascii=False, indent=2), encoding='utf8')
